param([int]$Port=8768,[string]$Symbol='XAUUSD')
$ErrorActionPreference='Stop';$listener=$null;$ab=$null;$stock=$null;$lastPrice=$null;$lastDirection='FLAT';$sequence=0;$fixedSymbol=$Symbol.Trim().ToUpperInvariant();$lastError=$null
function Ensure-Ab { try { if($null-eq $script:ab){$script:ab=New-Object -ComObject 'Broker.Application';$script:stock=$null};$true } catch {$script:lastError=$_.Exception.Message;$false} }
function Quote { if(-not(Ensure-Ab)){throw "AmiBroker OLE unavailable: $script:lastError"};if($null-eq $script:stock){$script:stock=$script:ab.Stocks.Item($script:fixedSymbol)};if($null-eq $script:stock){throw "Symbol '$script:fixedSymbol' not found"};$qs=$script:stock.Quotations;$count=[int]$qs.Count;if($count-le 0){throw 'No quotations'};$q=$qs.Item($count-1);$p=[double]$q.Close;if($p-le 0-or[double]::IsNaN($p)-or[double]::IsInfinity($p)){throw 'Invalid price'};$dir=$script:lastDirection;if($null-ne $script:lastPrice){if($p-gt$script:lastPrice){$dir='UP'}elseif($p-lt$script:lastPrice){$dir='DOWN'}};if($dir-notin @('UP','DOWN')){$dir='FLAT'};$script:lastPrice=$p;$script:lastDirection=$dir;$script:sequence++;[ordered]@{ok=$true;symbol=$script:fixedSymbol;price=[math]::Round($p,6);direction=$dir;sequence=$script:sequence;observedAt=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();source='AmiBroker.OLE.LastQuotation.Close'}}
function Read-Req($s){$r=New-Object IO.StreamReader($s,[Text.Encoding]::ASCII,$false,4096,$true);$line=$r.ReadLine();if([string]::IsNullOrWhiteSpace($line)){return $null};$a=$line.Split(' ');while(($h=$r.ReadLine())-ne $null-and$h-ne''){};[ordered]@{method=$a[0].ToUpperInvariant();target=$a[1]}}
function Reply($s,$code,$reason,$body){$b=[Text.Encoding]::UTF8.GetBytes($body);$headers=("HTTP/1.1 $code $reason`r`nContent-Type: application/json; charset=utf-8`r`nContent-Length: $($b.Length)`r`nAccess-Control-Allow-Origin: *`r`nAccess-Control-Allow-Methods: GET, OPTIONS`r`nAccess-Control-Allow-Headers: Content-Type, Accept, Cache-Control, Pragma, Private-Network`r`nAccess-Control-Allow-Private-Network: true`r`nCache-Control: no-store, no-cache, must-revalidate, max-age=0`r`nConnection: close`r`n`r`n");$h=[Text.Encoding]::ASCII.GetBytes($headers);$s.Write($h,0,$h.Length);if($b.Length){$s.Write($b,0,$b.Length)};$s.Flush()}
try{if(-not(Ensure-Ab)){throw "Cannot connect to AmiBroker: $script:lastError"};$listener=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback,$Port);$listener.Start();Write-Host "V499 PROFESSIONAL LINK READY: http://127.0.0.1:$Port/quote" -ForegroundColor Green;Write-Host "Symbol: $fixedSymbol - Keep this window open." -ForegroundColor Cyan;while($true){$c=$listener.AcceptTcpClient();try{$c.NoDelay=$true;$s=$c.GetStream();$s.ReadTimeout=1200;$s.WriteTimeout=1200;$req=Read-Req $s;if($null-eq$req){continue};if($req.method-eq'OPTIONS'){Reply $s 204 'No Content' '';continue};$path=([Uri]("http://127.0.0.1$($req.target)")).AbsolutePath.ToLowerInvariant();if($req.method-eq'GET'-and$path-eq'/health'){Reply $s 200 'OK' ([ordered]@{ok=(Ensure-Ab);service='amibroker-wheel-v499';symbol=$fixedSymbol;port=$Port;lastPrice=$lastPrice;error=$lastError}|ConvertTo-Json -Compress);continue};if($req.method-eq'GET'-and$path-eq'/quote'){try{Reply $s 200 'OK' (Quote|ConvertTo-Json -Compress)}catch{$lastError=$_.Exception.Message;Reply $s 503 'Service Unavailable' ([ordered]@{ok=$false;error=$lastError}|ConvertTo-Json -Compress)};continue};Reply $s 404 'Not Found' '{"ok":false,"error":"Not found"}'}finally{try{$c.Close()}catch{}}}}finally{if($listener){try{$listener.Stop()}catch{}};if($ab){try{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($ab)}catch{}}}
